SIGAP_SOURCES = {"__init__": "\"\"\"Sigap — Smart School Service Center prototype.\"\"\"\n", "config": "import os\nimport re\nfrom datetime import datetime\nfrom pathlib import Path\nfrom zoneinfo import ZoneInfo\n\nWIB = ZoneInfo(\"Asia/Jakarta\")\nROOT = Path(__file__).resolve().parent.parent\n\n\ndef _load_dotenv(path: Path) -> None:\n    \"\"\"Loads KEY=value lines from the project .env without overriding the real environment.\"\"\"\n    if not path.is_file():\n        return\n    for line in path.read_text(encoding=\"utf-8\").splitlines():\n        key, sep, value = line.strip().partition(\"=\")\n        if not (sep and key) or key.startswith(\"#\"):\n            continue\n        value = value.strip()\n        if value[:1] in ('\"', \"'\") and value[0] in value[1:]:  # quoted: keep what is inside, '#' included\n            value = value[1:value.index(value[0], 1)]\n        else:  # unquoted: ' # ...' is a comment, as in shells and Docker Compose\n            value = re.split(r\"\\s+#\", value, maxsplit=1)[0].strip()\n        os.environ.setdefault(key.strip(), value)\n\n\n_load_dotenv(ROOT / \".env\")\nDATA_DIR = Path(os.environ.get(\"SIGAP_DATA_DIR\", ROOT / \"data\"))\nOUTBOX_DIR = Path(os.environ.get(\"SIGAP_OUTBOX_DIR\", ROOT / \"outbox\"))\n\n\nSTUDENT_SERVICES_INBOX = os.environ.get(\"SIGAP_SERVICES_INBOX\", \"layanan.akademik@und.ac.id\")\n\n\ndef now() -> datetime:\n    \"\"\"Current time in WIB. SIGAP_NOW (e.g. 2026-10-04T19:00) pins it for demos and tests.\"\"\"\n    fixed = os.environ.get(\"SIGAP_NOW\")\n    if fixed:\n        dt = datetime.fromisoformat(fixed)\n        return dt if dt.tzinfo else dt.replace(tzinfo=WIB)\n    return datetime.now(WIB)\n", "textutil": "\"\"\"Language detection, tokenisation and date formatting shared by the tools.\"\"\"\nimport re\nfrom datetime import date, datetime\n\n_ID_MARKERS = set(\"\"\"\napa saja aja yang minggu ini kapan saya aku gue gw nggak ngga gak ga tidak bisa boleh kalau kalo dong sih nih ya iya\nharus ke di dan untuk berapa bagaimana gimana mana sudah udah belum masih tugas ujian besok hari dengan itu ada mau\ntolong kirim kirimkan siapa jadwal telat dinilai nilai buka tutup dibuka cuti kuliah mata deh lagi jam tanggal terima\nkasih halo hai pagi malam siang sore kerjain kerjakan bikin bikinin buatkan buatin esai apakah bulan depan sampai batas\nlho kok sekarang keluar caranya cara syarat aturan dikumpulkan pekan kak tenggat pengingat ingatkan oke\n\"\"\".split())\n_EN_MARKERS = set(\"\"\"\nwhat when is my the are due this week which can i how do does it we in of to for yes no please exam midterm late\nstill open closed has have will about rule assignment next tomorrow today who should where attendance minimum window\nwithdrawal leave grade hello hi thanks thank send you me write essay sure okay what's whats did get an a if am there\n\"\"\".split())\n\n\ndef detect_lang(text: str, default: str = \"id\") -> str:\n    words = re.findall(r\"[a-z']+\", text.lower())\n    id_score = sum(w in _ID_MARKERS for w in words)\n    en_score = sum(w in _EN_MARKERS for w in words)\n    if id_score == en_score:\n        return default\n    return \"id\" if id_score > en_score else \"en\"\n\n\n# Phrases folded before tokenising, so English and Indonesian questions meet the same index terms.\n_PHRASES = {\n    \"make-up\": \"susulan\", \"make up\": \"susulan\", \"makeup exam\": \"susulan ujian\",\n    \"student services\": \"layanan\", \"grade appeal\": \"banding nilai\",\n    \"add/drop\": \"tambah batal\", \"add drop\": \"tambah batal\",\n    \"ghost writer\": \"joki\", \"ghost-writing\": \"joki\",\n}\n\n_CANON = {\n    \"telat\": \"terlambat\", \"late\": \"terlambat\", \"lambat\": \"terlambat\", \"keterlambatan\": \"terlambat\", \"overdue\": \"terlambat\",\n    \"submit\": \"kumpul\", \"submission\": \"kumpul\", \"submitted\": \"kumpul\", \"dikumpulkan\": \"kumpul\", \"mengumpulkan\": \"kumpul\",\n    \"pengumpulan\": \"kumpul\", \"ngumpul\": \"kumpul\", \"ngumpulin\": \"kumpul\", \"kumpulkan\": \"kumpul\", \"resubmit\": \"kumpul\",\n    \"upload\": \"unggah\", \"diunggah\": \"unggah\", \"mengunggah\": \"unggah\", \"uploaded\": \"unggah\",\n    \"assignment\": \"tugas\", \"homework\": \"tugas\",\n    \"attendance\": \"hadir\", \"kehadiran\": \"hadir\", \"absen\": \"hadir\", \"absensi\": \"hadir\", \"presensi\": \"hadir\", \"attend\": \"hadir\",\n    \"absent\": \"izin\", \"absence\": \"izin\", \"permission\": \"izin\", \"excused\": \"izin\",\n    \"sick\": \"sakit\", \"ill\": \"sakit\", \"illness\": \"sakit\", \"medical\": \"sakit\",\n    \"minimum\": \"minimal\", \"percent\": \"persen\",\n    \"graded\": \"nilai\", \"grade\": \"nilai\", \"dinilai\": \"nilai\", \"score\": \"nilai\", \"penilaian\": \"nilai\", \"mark\": \"nilai\",\n    \"penalty\": \"potong\", \"potongan\": \"potong\", \"dipotong\": \"potong\", \"deduction\": \"potong\", \"penalti\": \"potong\", \"penalized\": \"potong\",\n    \"extension\": \"perpanjang\", \"perpanjangan\": \"perpanjang\", \"extend\": \"perpanjang\", \"diperpanjang\": \"perpanjang\",\n    \"deadline\": \"tenggat\", \"due\": \"tenggat\",\n    \"exam\": \"ujian\", \"test\": \"ujian\", \"midterm\": \"uts\", \"final\": \"uas\", \"finals\": \"uas\",\n    \"makeup\": \"susulan\", \"missed\": \"susulan\", \"miss\": \"susulan\",\n    \"plagiarism\": \"plagiat\", \"plagiarisme\": \"plagiat\", \"cheat\": \"curang\", \"cheating\": \"curang\", \"nyontek\": \"curang\",\n    \"contek\": \"curang\", \"mencontek\": \"curang\", \"menyontek\": \"curang\", \"chatgpt\": \"ai\", \"integrity\": \"integritas\",\n    \"appeal\": \"banding\", \"dispute\": \"banding\",\n    \"leave\": \"cuti\",\n    \"withdraw\": \"batal\", \"withdrawal\": \"batal\", \"pembatalan\": \"batal\", \"dibatalkan\": \"batal\", \"membatalkan\": \"batal\", \"drop\": \"batal\",\n    \"registration\": \"krs\", \"register\": \"krs\", \"enroll\": \"krs\", \"enrol\": \"krs\", \"enrollment\": \"krs\", \"credits\": \"sks\",\n    \"credit\": \"sks\", \"load\": \"beban\",\n    \"tuition\": \"ukt\", \"fee\": \"ukt\", \"fees\": \"ukt\", \"pay\": \"bayar\", \"payment\": \"bayar\", \"pembayaran\": \"bayar\",\n    \"installment\": \"cicil\", \"installments\": \"cicil\", \"cicilan\": \"cicil\", \"mencicil\": \"cicil\", \"nyicil\": \"cicil\",\n    \"retake\": \"ulang\", \"mengulang\": \"ulang\", \"repeat\": \"ulang\", \"perbaikan\": \"remedial\", \"fail\": \"gagal\", \"failed\": \"gagal\",\n    \"counseling\": \"konseling\", \"counselling\": \"konseling\", \"counselor\": \"konseling\", \"psychologist\": \"psikolog\",\n    \"stress\": \"stres\", \"stressed\": \"stres\", \"anxious\": \"cemas\", \"anxiety\": \"cemas\", \"depressed\": \"depresi\",\n    \"camera\": \"kamera\", \"proctoring\": \"pengawas\", \"proctor\": \"pengawas\", \"connection\": \"koneksi\", \"disconnected\": \"putus\",\n    \"contact\": \"kontak\", \"hours\": \"jam\", \"office\": \"kantor\",\n    \"letter\": \"surat\", \"doctor\": \"dokter\", \"note\": \"surat\",\n    \"transcript\": \"transkrip\", \"scale\": \"skala\", \"gpa\": \"ipk\", \"pass\": \"lulus\", \"passing\": \"lulus\",\n    \"eligible\": \"syarat\", \"eligibility\": \"syarat\", \"requirement\": \"syarat\", \"requirements\": \"syarat\", \"persyaratan\": \"syarat\",\n    \"mengajukan\": \"ajukan\", \"pengajuan\": \"ajukan\", \"diajukan\": \"ajukan\", \"apply\": \"ajukan\", \"request\": \"ajukan\",\n    \"procedure\": \"prosedur\", \"process\": \"prosedur\", \"steps\": \"prosedur\", \"caranya\": \"cara\",\n    \"email\": \"email\", \"whatsapp\": \"email\", \"wa\": \"email\",\n}\n\n_STOP = set(\"\"\"\nsaya aku gue gw apa yang dan di ke dari untuk ini itu ada kalau kalo masih nggak ngga gak ga tidak bisa boleh dong sih nih\nya harus siapa bagaimana gimana berapa kapan mana apakah atau dengan pada juga akan sudah udah belum lagi jadi kok deh\nthe a an is are am was were be been can could i my me do does did what how when who which if still will would to of in\non for and or it its with at after before about there any get should we you your our this that than so not no yes may\nmata kuliah course courses class mau aja saja kah tolong please kak min sama nya kita kami tentang soal lho\nbanget bantu help gimana\n\"\"\".split())\n\n\ndef _fold(text: str) -> str:\n    t = text.lower()\n    for phrase, repl in _PHRASES.items():\n        t = t.replace(phrase, repl)\n    return t\n\n\ndef _stem(w: str) -> str:\n    for suf in (\"nya\", \"lah\", \"kah\"):\n        if w.endswith(suf) and len(w) > len(suf) + 3:\n            w = w[: -len(suf)]\n            break\n    if w.endswith(\"s\") and w[:-1] in _CANON:  # English plurals only; Indonesian words often end in s\n        w = w[:-1]\n    return w\n\n\ndef tokens(text: str) -> list[str]:\n    out = []\n    for raw in re.findall(r\"[a-z0-9]+\", _fold(text)):\n        if raw in _STOP:\n            continue\n        w = _CANON.get(raw) or _CANON.get(_stem(raw)) or _stem(raw)\n        if w and w not in _STOP:\n            out.append(w)\n    return out\n\n\n_DAYS = {\"id\": [\"Sen\", \"Sel\", \"Rab\", \"Kam\", \"Jum\", \"Sab\", \"Min\"], \"en\": [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\"]}\n_MONTHS = {\n    \"id\": [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"Mei\", \"Jun\", \"Jul\", \"Agu\", \"Sep\", \"Okt\", \"Nov\", \"Des\"],\n    \"en\": [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\", \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"],\n}\n\n\ndef fmt_date(d: date, lang: str) -> str:\n    return f\"{_DAYS[lang][d.weekday()]}, {d.day} {_MONTHS[lang][d.month - 1]} {d.year}\"\n\n\ndef fmt_dt(dt: datetime, lang: str, end: datetime | None = None) -> str:\n    t = dt.strftime(\"%H:%M\")\n    if end:\n        t += f\"–{end.strftime('%H:%M')}\"\n    return f\"{fmt_date(dt.date(), lang)} · {t} WIB\"\n", "data": "\"\"\"Loads the structured sources. Dates only ever come from these tables.\"\"\"\nimport csv\nimport re\nfrom dataclasses import dataclass\nfrom datetime import date, datetime, time\nfrom functools import lru_cache\nfrom pathlib import Path\n\nfrom .config import DATA_DIR, WIB\n\n\n@dataclass(frozen=True)\nclass Course:\n    code: str\n    name_id: str\n    name_en: str\n    lecturer: str\n    aliases: tuple[str, ...]\n\n    def name(self, lang: str) -> str:\n        return self.name_en if lang == \"en\" else self.name_id\n\n\n@dataclass(frozen=True)\nclass ScheduleItem:\n    item_id: str\n    course: Course\n    title_id: str\n    title_en: str\n    type: str  # assignment | quiz | project | exam\n    due: datetime  # deadline, or exam start\n    end: datetime | None  # exam/quiz end\n    where: str\n    source: str\n\n    def title(self, lang: str) -> str:\n        return self.title_en if lang == \"en\" else self.title_id\n\n\n@dataclass(frozen=True)\nclass CalendarEntry:\n    kind: str  # term | period | window\n    key: str\n    name_id: str\n    name_en: str\n    start: date\n    end: date\n    note_id: str\n    note_en: str\n\n    def name(self, lang: str) -> str:\n        return self.name_en if lang == \"en\" else self.name_id\n\n    def note(self, lang: str) -> str:\n        return self.note_en if lang == \"en\" else self.note_id\n\n\n@dataclass(frozen=True)\nclass Section:\n    number: str\n    title_id: str\n    title_en: str\n    tags: tuple[str, ...]\n    text_id: str\n    text_en: str\n\n    def title(self, lang: str) -> str:\n        return self.title_en if lang == \"en\" else self.title_id\n\n    def text(self, lang: str) -> str:\n        return self.text_en if lang == \"en\" else self.text_id\n\n\n@dataclass(frozen=True)\nclass Document:\n    path: Path\n    meta: dict\n    sections: tuple[Section, ...]\n\n    def title(self, lang: str) -> str:\n        return self.meta.get(f\"title_{lang}\") or self.meta[\"title_id\"]\n\n\ndef _read_csv(name: str) -> list[dict]:\n    with open(DATA_DIR / name, newline=\"\", encoding=\"utf-8\") as f:\n        return list(csv.DictReader(f))\n\n\n@lru_cache\ndef courses() -> dict[str, Course]:\n    out = {}\n    for r in _read_csv(\"courses.csv\"):\n        aliases = tuple(a.strip().lower() for a in r[\"aliases\"].split(\";\") if a.strip())\n        out[r[\"course_code\"]] = Course(r[\"course_code\"], r[\"name_id\"], r[\"name_en\"], r[\"lecturer\"], aliases)\n    return out\n\n\ndef _at(d: str, t: str) -> datetime:\n    return datetime.combine(date.fromisoformat(d), time.fromisoformat(t), tzinfo=WIB)\n\n\n@lru_cache\ndef schedule() -> tuple[ScheduleItem, ...]:\n    cs = courses()\n    items = []\n    for r in _read_csv(\"course_schedule.csv\"):\n        items.append(ScheduleItem(\n            item_id=r[\"item_id\"],\n            course=cs[r[\"course_code\"]],\n            title_id=r[\"title_id\"],\n            title_en=r[\"title_en\"],\n            type=r[\"type\"],\n            due=_at(r[\"due_date\"], r[\"due_time\"]),\n            end=_at(r[\"due_date\"], r[\"end_time\"]) if r[\"end_time\"] else None,\n            where=r[\"where\"],\n            source=r[\"source\"],\n        ))\n    return tuple(sorted(items, key=lambda i: i.due))\n\n\n@lru_cache\ndef calendar() -> tuple[CalendarEntry, ...]:\n    return tuple(\n        CalendarEntry(r[\"kind\"], r[\"key\"], r[\"name_id\"], r[\"name_en\"],\n                      date.fromisoformat(r[\"start\"]), date.fromisoformat(r[\"end\"]),\n                      r[\"note_id\"], r[\"note_en\"])\n        for r in _read_csv(\"academic_calendar.csv\")\n    )\n\n\n_SECTION_RE = re.compile(r\"^##\\s+(?P<num>[\\d.]+)\\s*\\|\\s*(?P<tid>[^|]+?)\\s*\\|\\s*(?P<ten>.+?)\\s*$\")\n\n\ndef _parse_document(path: Path) -> Document:\n    text = path.read_text(encoding=\"utf-8\")\n    meta: dict = {}\n    body = text\n    if text.startswith(\"---\"):\n        _, front, body = text.split(\"---\", 2)\n        for line in front.strip().splitlines():\n            k, _, v = line.partition(\":\")\n            meta[k.strip()] = v.strip()\n    sections, cur = [], None\n    for line in body.splitlines():\n        m = _SECTION_RE.match(line)\n        if m:\n            cur = {\"num\": m[\"num\"], \"tid\": m[\"tid\"], \"ten\": m[\"ten\"], \"tags\": \"\", \"id\": \"\", \"en\": \"\"}\n            sections.append(cur)\n        elif cur is not None:\n            for key, prefix in ((\"tags\", \"tags:\"), (\"id\", \"ID:\"), (\"en\", \"EN:\")):\n                if line.startswith(prefix):\n                    cur[key] = line[len(prefix):].strip()\n    return Document(path, meta, tuple(\n        Section(s[\"num\"], s[\"tid\"], s[\"ten\"],\n                tuple(t.strip().lower() for t in s[\"tags\"].split(\",\") if t.strip()),\n                s[\"id\"], s[\"en\"])\n        for s in sections\n    ))\n\n\n@lru_cache\ndef documents() -> tuple[Document, ...]:\n    \"\"\"Current handbook versions. Superseded files (meta 'superseded: true') are excluded (FR-10).\"\"\"\n    docs = [_parse_document(p) for p in sorted((DATA_DIR / \"handbook\").glob(\"*.md\"))]\n    return tuple(d for d in docs if d.meta.get(\"superseded\", \"\").lower() != \"true\")\n", "retrieval": "\"\"\"Keyword (BM25) retrieval over handbook sections, with a strict NOT_FOUND gate.\n\nStands in for the Astra DB vector search of the Langflow build. The gate matters more\nthan the ranking: when evidence is weak Sigap must say NOT_FOUND rather than stretch a\nloosely related section into an answer.\n\"\"\"\nimport math\nfrom collections import Counter\nfrom dataclasses import dataclass\nfrom functools import lru_cache\n\nfrom .data import Document, Section, documents\nfrom .textutil import tokens\n\n# A section counts as an answer only if the question hits enough of its curated tags,\n# or one tag that belongs to this section alone and covers most of the question.\nMIN_TAG_HITS = 2\nMIN_SCORE = 4.0\nMIN_COVERAGE_SINGLE_TAG = 0.5\n\n\n@dataclass\nclass Hit:\n    doc: Document\n    section: Section\n    score: float\n    tag_hits: list[str]\n    unique_tag_hits: list[str]\n    coverage: float\n\n\n@dataclass\nclass _Entry:\n    doc: Document\n    section: Section\n    tf: Counter\n    length: int\n    tag_terms: set\n\n\n@lru_cache\ndef _index():\n    entries = []\n    for doc in documents():\n        for s in doc.sections:\n            tag_terms = set(tokens(\" \".join(s.tags)))\n            # Tags are weighted x3: they are the staff-curated vocabulary for the section.\n            terms = tokens(f\"{s.title_id} {s.title_en} {s.text_id} {s.text_en}\") + list(tag_terms) * 3\n            entries.append(_Entry(doc, s, Counter(terms), len(terms), tag_terms))\n    n = len(entries)\n    df = Counter(t for e in entries for t in e.tf)\n    idf = {t: math.log(1 + (n - c + 0.5) / (c + 0.5)) for t, c in df.items()}\n    avg = sum(e.length for e in entries) / max(n, 1)\n    tag_df = Counter(t for e in entries for t in e.tag_terms)\n    return entries, idf, avg, tag_df\n\n\ndef search(question: str, k: int = 3) -> list[Hit]:\n    entries, idf, avg, tag_df = _index()\n    q = set(tokens(question))\n    k1, b = 1.4, 0.75\n    hits = []\n    for e in entries:\n        score = 0.0\n        for t in q:\n            f = e.tf.get(t, 0)\n            if f:\n                score += idf[t] * f * (k1 + 1) / (f + k1 * (1 - b + b * e.length / avg))\n        if score:\n            tag_hits = sorted(q & e.tag_terms)\n            matched = sum(1 for t in q if t in e.tf)\n            hits.append(Hit(e.doc, e.section, score, tag_hits,\n                            [t for t in tag_hits if tag_df[t] == 1], matched / len(q)))\n    hits.sort(key=lambda h: h.score, reverse=True)\n    return hits[:k]\n\n\ndef supports(text: str, section_number: str) -> bool:\n    \"\"\"True if `text` on its own confidently retrieves that section. Used to check an LLM-rewritten query\n    against the student's original words, so added keywords cannot manufacture an answer.\"\"\"\n    return any(h.section.number == section_number and is_confident(h) for h in search(text, k=5))\n\n\ndef is_confident(hit: Hit | None) -> bool:\n    if not hit:\n        return False\n    if len(hit.tag_hits) >= MIN_TAG_HITS and hit.score >= MIN_SCORE:\n        return True\n    return bool(hit.unique_tag_hits) and hit.coverage >= MIN_COVERAGE_SINGLE_TAG\n", "tools": "\"\"\"The five Sigap tools from the PRD. Same names and contracts as the Langflow flows.\n\nEach tool returns a dict: structured fields for programs, plus `text` ready to show a\nstudent. Dates are only read from data tables here; nothing computes a date from model output.\n\"\"\"\nimport csv\nimport json\nimport os\nimport re\nimport smtplib\nimport uuid\nfrom datetime import datetime, time, timedelta\nfrom email.message import EmailMessage\nfrom urllib.parse import quote\n\nfrom . import data\nfrom .config import OUTBOX_DIR, STUDENT_SERVICES_INBOX, WIB, now\nfrom .retrieval import is_confident, search, supports\nfrom .textutil import detect_lang, fmt_date, fmt_dt\n\nTYPE_LABEL = {\n    \"id\": {\"assignment\": \"Tugas\", \"quiz\": \"Kuis\", \"project\": \"Proyek\", \"exam\": \"Ujian\"},\n    \"en\": {\"assignment\": \"Assignment\", \"quiz\": \"Quiz\", \"project\": \"Project\", \"exam\": \"Exam\"},\n}\n\n\ndef _lang(lang: str | None, text: str = \"\") -> str:\n    return lang if lang in (\"id\", \"en\") else detect_lang(text)\n\n\n# ---------------------------------------------------------------- shared lookups\n\ndef find_course(text: str) -> data.Course | None:\n    t = f\" {text.lower()} \"\n    best, best_len = None, 0\n    for c in data.courses().values():\n        for a in (*c.aliases, c.name_id.lower(), c.name_en.lower(), c.code.lower()):\n            if re.search(rf\"(?<![a-z0-9]){re.escape(a)}(?![a-z0-9])\", t) and len(a) > best_len:\n                best, best_len = c, len(a)\n    return best\n\n\ndef find_item(item_id: str) -> data.ScheduleItem | None:\n    return next((i for i in data.schedule() if i.item_id.lower() == item_id.strip().lower()), None)\n\n\ndef _end_of_day(d) -> datetime:\n    return datetime.combine(d, time(23, 59, 59), tzinfo=WIB)\n\n\ndef parse_range(text: str, n: datetime, open_ended: bool) -> tuple[datetime, datetime, str]:\n    \"\"\"Turns 'this week', 'besok', 'next 14 days'… into a [from, to] window starting now.\"\"\"\n    t = text.lower()\n    today = n.date()\n    if re.search(r\"hari ini|today|tonight|malam ini|nanti malam\", t):\n        return n, _end_of_day(today), \"today\"\n    if re.search(r\"\\bbesok\\b|tomorrow\", t):\n        d = today + timedelta(days=1)\n        return datetime.combine(d, time(0), tzinfo=WIB), _end_of_day(d), \"tomorrow\"\n    if re.search(r\"minggu depan|pekan depan|next week\", t):\n        a = today + timedelta(days=7)\n        return datetime.combine(a, time(0), tzinfo=WIB), _end_of_day(a + timedelta(days=6)), \"next_week\"\n    m = re.search(r\"(\\d+)\\s*(hari|days?)\", t)\n    if m:\n        days = max(1, min(int(m.group(1)), 120))\n        return n, _end_of_day(today + timedelta(days=days - 1)), f\"{days}_days\"\n    if re.search(r\"bulan ini|this month\", t):\n        nxt = (today.replace(day=28) + timedelta(days=4)).replace(day=1)\n        return n, _end_of_day(nxt - timedelta(days=1)), \"this_month\"\n    if re.search(r\"minggu ini|pekan ini|this week|seminggu|week\", t) or not open_ended:\n        return n, _end_of_day(today + timedelta(days=6)), \"7_days\"\n    return n, _end_of_day(today + timedelta(days=180)), \"upcoming\"\n\n\ndef _range_label(label: str, a: datetime, b: datetime, lang: str) -> str:\n    span = f\"{fmt_date(a.date(), lang)} – {fmt_date(b.date(), lang)}\"\n    names = {\n        \"id\": {\"today\": \"hari ini\", \"tomorrow\": \"besok\", \"next_week\": \"minggu depan\", \"7_days\": \"7 hari ke depan\",\n               \"this_month\": \"bulan ini\", \"upcoming\": \"yang akan datang\"},\n        \"en\": {\"today\": \"today\", \"tomorrow\": \"tomorrow\", \"next_week\": \"next week\", \"7_days\": \"the next 7 days\",\n               \"this_month\": \"this month\", \"upcoming\": \"upcoming\"},\n    }[lang]\n    if label.endswith(\"_days\") and label not in names:\n        name = f\"{label.split('_')[0]} hari ke depan\" if lang == \"id\" else f\"the next {label.split('_')[0]} days\"\n    else:\n        name = names[label]\n    return name if label == \"upcoming\" else f\"{name} ({span})\"\n\n\ndef item_dict(i: data.ScheduleItem, lang: str, n: datetime) -> dict:\n    hours_left = (i.due - n).total_seconds() / 3600\n    return {\n        \"item_id\": i.item_id,\n        \"course_code\": i.course.code,\n        \"course\": i.course.name(lang),\n        \"item\": i.title(lang),\n        \"type\": i.type,\n        \"type_label\": TYPE_LABEL[lang][i.type],\n        \"due\": i.due.isoformat(),\n        \"end\": i.end.isoformat() if i.end else None,\n        \"due_text\": fmt_dt(i.due, lang, i.end),\n        \"where\": i.where,\n        \"source\": i.source,\n        \"due_today\": i.due.date() == n.date(),\n        \"hours_left\": round(hours_left, 1),\n    }\n\n\n# ---------------------------------------------------------------- tool 1\n\ndef get_my_deadlines(request: str = \"this week\", course: str | None = None, item_type: str | None = None,\n                     language: str | None = None, courses: list[str] | str | None = None) -> dict:\n    \"\"\"Lists the student's upcoming deadlines and exams from the official course schedule.\n    courses: the student's enrolled course codes (the backend sends these; never a student identity).\"\"\"\n    lang = _lang(language, request)\n    n = now()\n    text = f\"{request} {course or ''}\".lower()\n    c = find_course(course) if course else find_course(request)\n\n    kind = (item_type or \"\").lower() or None\n    subtype = None\n    if re.search(r\"\\b(uts|midterm|mid-term|tengah semester)\\b\", text):\n        kind, subtype = \"exam\", \"UTS\"\n    elif re.search(r\"\\b(uas|final exam|finals|akhir semester)\\b\", text):\n        kind, subtype = \"exam\", \"UAS\"\n    elif re.search(r\"\\b(ujian|exam|exams|test)\\b\", text):\n        kind = \"exam\"\n    elif re.search(r\"\\b(kuis|quiz|quizzes)\\b\", text):\n        kind = \"quiz\"\n\n    if isinstance(courses, str):\n        courses = [x.strip() for x in courses.split(\",\") if x.strip()]\n    enrolled = {x.upper() for x in courses} if courses is not None else None\n    a, b, label = parse_range(text, n, open_ended=bool(c or kind))\n    items = [\n        i for i in data.schedule()\n        if a <= i.due <= b\n        and (enrolled is None or i.course.code in enrolled)\n        and (c is None or i.course.code == c.code)\n        and (kind is None or i.type == kind)\n        and (subtype is None or i.item_id.endswith(subtype))\n    ]\n    rows = [item_dict(i, lang, n) for i in items]\n    rng = _range_label(label, a, b, lang)\n\n    scope = (c.name(lang) + \" · \") if c else \"\"\n    if not rows:\n        msg = (f\"Tidak ada tenggat {scope}untuk {rng} di jadwal resmi.\" if lang == \"id\"\n               else f\"Nothing {scope}is due in {rng} on the official schedule.\")\n    else:\n        head = (f\"Tenggat {scope}{rng} — {len(rows)} item:\" if lang == \"id\"\n                else f\"Due {scope}{rng} — {len(rows)} item(s):\")\n        lines = [head]\n        for r in rows:\n            flag = (\"⚠️ HARI INI · \" if lang == \"id\" else \"⚠️ TODAY · \") if r[\"due_today\"] else \"\"\n            lines.append(f\"- {flag}{r['due_text']} — {r['course']}: {r['item']} ({r['type_label']})\")\n        msg = \"\\n\".join(lines)\n    src = \"Jadwal mata kuliah resmi (tabel jadwal)\" if lang == \"id\" else \"Official course schedule (schedule table)\"\n    return {\n        \"tool\": \"get_my_deadlines\",\n        \"language\": lang,\n        \"now\": n.isoformat(),\n        \"range\": {\"from\": a.isoformat(), \"to\": b.isoformat(), \"label\": rng},\n        \"course_filter\": c.code if c else None,\n        \"type_filter\": kind,\n        \"items\": rows,\n        \"source\": src,\n        \"text\": f\"{msg}\\n\\nSumber: {src}\" if lang == \"id\" else f\"{msg}\\n\\nSource: {src}\",\n    }\n\n\n# ---------------------------------------------------------------- tool 2\n\nWINDOW_TOPICS = {\n    \"krs\": r\"\\bkrs\\b|registrasi|registration|register|enrol\",\n    \"add-drop\": r\"add.?drop|perubahan krs|tambah.?batal|ubah krs\",\n    \"cuti\": r\"\\bcuti\\b|\\bleave\\b\",\n    \"pembatalan\": r\"pembatalan|batal(kan)? (mata kuliah|matkul)|withdraw|\\bdrop\\b\",\n    \"ukt-2\": r\"\\bukt\\b|bayar|pembayaran|tuition|payment|cicilan|installment\",\n    \"uts-susulan\": r\"susulan|make.?up\",\n    \"banding-nilai\": r\"banding|appeal\",\n    \"nilai\": r\"nilai (akhir )?(keluar|publikasi|diumumkan)|publikasi nilai|grades? (out|release|published)\",\n    \"uts\": r\"\\buts\\b|midterm\",\n    \"uas\": r\"\\buas\\b|final exam|finals\",\n}\n\n\ndef detect_window_topic(text: str) -> str | None:\n    t = text.lower()\n    for key, pat in WINDOW_TOPICS.items():\n        if re.search(pat, t):\n            return key\n    return None\n\n\ndef get_study_period(on_date: str | None = None, topic: str | None = None, language: str | None = None) -> dict:\n    \"\"\"Tells which academic week and period a date falls in and which windows are open.\"\"\"\n    lang = _lang(language, topic or \"\")\n    n = now()\n    d = datetime.fromisoformat(on_date).date() if on_date else n.date()\n    cal = data.calendar()\n    term = next((e for e in cal if e.kind == \"term\" and e.start <= d <= e.end), None)\n    period = next((e for e in cal if e.kind == \"period\" and e.start <= d <= e.end), None)\n    week = (d - term.start).days // 7 + 1 if term else None\n    windows = [e for e in cal if e.kind == \"window\"]\n    open_w = [e for e in windows if e.start <= d <= e.end]\n    soon = [e for e in windows if d < e.start <= d + timedelta(days=30)]\n\n    topic_key = (topic if topic in {e.key for e in windows} else detect_window_topic(topic or \"\")) if topic else None\n    topic_entry = None\n    if topic_key:\n        cands = sorted((e for e in windows if e.key.startswith(topic_key)), key=lambda e: (e.end < d, e.start))\n        topic_entry = cands[0] if cands else None\n\n    def wline(e) -> str:\n        if e.start == e.end:\n            span = fmt_date(e.start, lang)\n        else:\n            span = f\"{fmt_date(e.start, lang)} – {fmt_date(e.end, lang)}\"\n        return f\"{e.name(lang)}: {span}\"\n\n    lines = []\n    if topic_entry:\n        e = topic_entry\n        left = (e.end - d).days\n        if e.start <= d <= e.end:\n            lines.append(f\"✅ {e.name(lang)} \" + (f\"MASIH DIBUKA sampai {fmt_date(e.end, lang)} (sisa {left} hari).\"\n                                                if lang == \"id\" else\n                                                f\"is OPEN until {fmt_date(e.end, lang)} ({left} days left).\"))\n        elif d < e.start:\n            lines.append(f\"⏳ {e.name(lang)} \" + (f\"BELUM DIBUKA — dibuka {fmt_date(e.start, lang)} s.d. {fmt_date(e.end, lang)}.\"\n                                                 if lang == \"id\" else\n                                                 f\"is NOT OPEN YET — runs {fmt_date(e.start, lang)} to {fmt_date(e.end, lang)}.\"))\n        else:\n            lines.append(f\"⛔ {e.name(lang)} \" + (f\"SUDAH DITUTUP pada {fmt_date(e.end, lang)}.\"\n                                                 if lang == \"id\" else f\"CLOSED on {fmt_date(e.end, lang)}.\"))\n        if e.note(lang):\n            lines.append(f\"   {e.note(lang)}\")\n        lines.append(\"\")\n\n    if term:\n        if lang == \"id\":\n            lines.append(f\"Hari ini {fmt_date(d, lang)}: {term.name(lang)}, minggu ke-{week}\"\n                         + (f\" — {period.name(lang)}.\" if period else \".\"))\n        else:\n            lines.append(f\"Today is {fmt_date(d, lang)}: {term.name(lang)}, week {week}\"\n                         + (f\" — {period.name(lang)}.\" if period else \".\"))\n    else:\n        lines.append(\"Tanggal ini di luar semester berjalan.\" if lang == \"id\" else \"This date is outside the current term.\")\n    if open_w:\n        lines.append(\"Sedang dibuka:\" if lang == \"id\" else \"Open now:\")\n        lines += [f\"- {wline(e)}\" for e in open_w]\n    if soon:\n        lines.append(\"Segera (30 hari ke depan):\" if lang == \"id\" else \"Coming up (next 30 days):\")\n        lines += [f\"- {wline(e)}\" for e in soon]\n    src = \"Kalender Akademik Ganjil 2026/2027 (tabel kalender)\" if lang == \"id\" else \"Academic Calendar Odd 2026/2027 (calendar table)\"\n    lines.append(f\"\\n{'Sumber' if lang == 'id' else 'Source'}: {src}\")\n\n    def wd(e):\n        return {\"key\": e.key, \"name\": e.name(lang), \"start\": e.start.isoformat(), \"end\": e.end.isoformat(), \"note\": e.note(lang)}\n\n    return {\n        \"tool\": \"get_study_period\",\n        \"language\": lang,\n        \"date\": d.isoformat(),\n        \"term\": term.name(lang) if term else None,\n        \"week\": week,\n        \"period\": period.name(lang) if period else None,\n        \"open_windows\": [wd(e) for e in open_w],\n        \"upcoming_windows\": [wd(e) for e in soon],\n        \"topic\": wd(topic_entry) | {\"status\": \"open\" if topic_entry.start <= d <= topic_entry.end\n                                    else \"not_yet\" if d < topic_entry.start else \"closed\"} if topic_entry else None,\n        \"source\": src,\n        \"text\": \"\\n\".join(lines).strip(),\n    }\n\n\n# ---------------------------------------------------------------- tool 3\n\ndef answer_campus_policy(question: str, language: str | None = None, support_text: str | None = None) -> dict:\n    \"\"\"Answers a campus-rule question using only the uploaded official documents, or NOT_FOUND.\n    support_text: the student's original message; when given, the article must match it too.\"\"\"\n    lang = _lang(language, support_text or question)\n    hits = search(question)\n    top = hits[0] if hits else None\n    if top and support_text and not supports(support_text, top.section.number):\n        top = None  # the (rewritten) query matched, the student's own words do not: don't stretch an article\n    checked = [f\"{d.title(lang)} v{d.meta.get('version')}\" for d in data.documents()]\n    if not is_confident(top):\n        msg = (\"Aku tidak menemukan aturan yang menjawab pertanyaan ini di dokumen resmi kampus, jadi aku tidak akan menebak.\"\n               if lang == \"id\" else\n               \"I couldn't find a rule that answers this in the campus's official documents, so I won't guess.\")\n        return {\n            \"tool\": \"answer_campus_policy\",\n            \"status\": \"NOT_FOUND\",\n            \"language\": lang,\n            \"checked_sources\": checked,\n            \"closest_section\": f\"§{top.section.number} {top.section.title(lang)}\" if top else None,\n            \"text\": msg,\n        }\n    doc, s = top.doc, top.section\n    eff = datetime.fromisoformat(doc.meta[\"effective\"]).date()\n    citation = {\n        \"document\": doc.title(lang),\n        \"version\": doc.meta.get(\"version\"),\n        \"effective\": doc.meta[\"effective\"],\n        \"section\": s.number,\n        \"section_title\": s.title(lang),\n    }\n    cite = (f\"{doc.title(lang)} v{citation['version']} (berlaku {fmt_date(eff, lang)}), Pasal {s.number} — {s.title(lang)}\"\n            if lang == \"id\" else\n            f\"{doc.title(lang)} v{citation['version']} (effective {fmt_date(eff, lang)}), Article {s.number} — {s.title(lang)}\")\n    return {\n        \"tool\": \"answer_campus_policy\",\n        \"status\": \"FOUND\",\n        \"language\": lang,\n        \"answer\": s.text(lang),\n        \"citation\": citation,\n        \"citation_text\": cite,\n        \"checked_sources\": checked,\n        \"text\": f\"{s.text(lang)}\\n\\n{'Sumber' if lang == 'id' else 'Source'}: {cite}\",\n    }\n\n\n# ---------------------------------------------------------------- tool 4\n\n# Inside the bot's agent the student confirms with a button the backend shows, so the agent must not call the\n# action tool again (models that did so looped until the step limit). Students' own agents (MCP) confirm by calling again.\n_BUTTON_NOTE = {\n    \"id\": \"BELUM dibuat atau dikirim. Sistem menampilkan tombol konfirmasi di bawah balasanmu. \"\n          \"Jangan panggil alat ini lagi dalam balasan ini; tulis balasan akhir untuk mahasiswa sekarang.\",\n    \"en\": \"NOT created or sent yet. The system shows a confirm button below your reply. \"\n          \"Do not call this tool again in this reply; write your final reply to the student now.\",\n}\n\n\ndef plan_reminders(item: data.ScheduleItem, n: datetime) -> dict:\n    \"\"\"Default plan: a reminder 3 days before and two 90-minute evening study blocks.\n    Every time is derived from the schedule row, never from the model.\"\"\"\n    due_day = item.due.date()\n    reminder = datetime.combine(due_day - timedelta(days=3), time(19, 0), tzinfo=WIB)\n    blocks = []\n    for back in (2, 1):\n        start = datetime.combine(due_day - timedelta(days=back), time(19, 30), tzinfo=WIB)\n        blocks.append((start, start + timedelta(minutes=90)))\n    if item.type == \"exam\" and item.due.hour >= 19:  # evening exam: last block the same morning instead\n        blocks[-1] = (item.due.replace(hour=9, minute=0), item.due.replace(hour=10, minute=30))\n    blocks = [(a, b) for a, b in blocks if a > n and b < item.due]\n    if reminder <= n:\n        reminder = item.due - timedelta(hours=2)\n        if reminder <= n:\n            reminder = None\n    return {\"reminder\": reminder, \"blocks\": blocks}\n\n\n_WEEKDAYS = {\"senin\": 0, \"monday\": 0, \"selasa\": 1, \"tuesday\": 1, \"rabu\": 2, \"wednesday\": 2, \"kamis\": 3, \"thursday\": 3,\n             \"jumat\": 4, \"jum'at\": 4, \"friday\": 4, \"sabtu\": 5, \"saturday\": 5, \"hari minggu\": 6, \"sunday\": 6}\n_MONTH_WORDS = {\"jan\": 1, \"januari\": 1, \"january\": 1, \"feb\": 2, \"februari\": 2, \"february\": 2, \"mar\": 3, \"maret\": 3,\n                \"march\": 3, \"apr\": 4, \"april\": 4, \"mei\": 5, \"may\": 5, \"jun\": 6, \"juni\": 6, \"june\": 6, \"jul\": 7, \"juli\": 7,\n                \"july\": 7, \"agu\": 8, \"agt\": 8, \"agustus\": 8, \"aug\": 8, \"august\": 8, \"sep\": 9, \"sept\": 9, \"september\": 9,\n                \"okt\": 10, \"oktober\": 10, \"oct\": 10, \"october\": 10, \"nov\": 11, \"november\": 11, \"des\": 12, \"desember\": 12,\n                \"dec\": 12, \"december\": 12}\n_UNIT = r\"(menit|mins?|minutes?|jam|hours?|hrs?|hari|days?)\"\n_PART_OF_DAY = [(r\"\\b(pagi|morning)\\b\", \"am\", 7), (r\"\\b(siang|noon|midday)\\b\", \"noon\", 12),\n                (r\"\\b(sore|afternoon)\\b\", \"pm\", 16), (r\"\\b(malam|evening|night|tonight)\\b\", \"pm\", 20)]\n\n\ndef _delta(num: str, unit: str) -> timedelta:\n    k = 1 if num in (\"se\", \"a\", \"an\", \"satu\", \"one\") else float(num.replace(\",\", \".\"))\n    if unit.startswith((\"menit\", \"min\")):\n        return timedelta(minutes=k)\n    if unit.startswith((\"jam\", \"hour\", \"hr\")):\n        return timedelta(hours=k)\n    return timedelta(days=k)\n\n\ndef parse_remind_at(text: str, n: datetime, due: datetime) -> tuple[datetime | None, str | None]:\n    \"\"\"Turns the student's own words (\"jam 8 malam\", \"besok 07.00\", \"2 jam sebelum deadline\", \"H-1\",\n    \"in 30 minutes\", or an ISO time) into an exact time. Returns (time, None) or (None, reason) where reason is\n    'unclear', 'past' or 'after_due'. Done in code so the model never computes a time.\"\"\"\n    t = \" \" + (text or \"\").lower().replace(\"’\", \"'\") + \" \"\n    at = None\n    try:  # an exact ISO time (what the backend stores between the preview and the yes): only validate it\n        iso = datetime.fromisoformat(text.strip())\n        return _check_remind_at(iso if iso.tzinfo else iso.replace(tzinfo=WIB), n, due)\n    except ValueError:\n        pass\n    # explicit clock time: 20:00 / 20.00 / jam 8 / pukul 8 / at 8 / 8pm / 8 am\n    hour = minute = None\n    m = (re.search(r\"\\b(\\d{1,2})[:.](\\d{2})\\s*(am|pm|a\\.m\\.|p\\.m\\.)?(?!\\d)\", t)\n         or re.search(r\"\\b(?:jam|pukul|pkl\\.?|at|@)\\s*(\\d{1,2})(?:[:.](\\d{2}))?\\s*(am|pm)?\\b\", t)\n         or re.search(r\"\\b(\\d{1,2})(?:[:.](\\d{2}))?\\s*(am|pm|a\\.m\\.|p\\.m\\.)\", t))\n    if m and not re.search(r\"^\\s*\" + _UNIT + r\"\\s*(sebelum|before|lagi|from now)\", t[m.end():]):\n        hour, minute, ampm = int(m.group(1)), int(m.group(2) or 0), (m.group(3) or \"\").replace(\".\", \"\")\n        if ampm == \"pm\" and hour < 12:\n            hour += 12\n        elif ampm == \"am\" and hour == 12:\n            hour = 0\n        elif not ampm:\n            for pat, kind, _ in _PART_OF_DAY:\n                if re.search(pat, t):\n                    if kind == \"pm\" and hour < 12:\n                        hour += 12\n                    elif kind == \"noon\" and hour < 6:  # \"jam 1 siang\" = 13:00\n                        hour += 12\n                    break\n        if hour > 23 or minute > 59:\n            return None, \"unclear\"\n    default_hour = next((h for pat, _, h in _PART_OF_DAY if re.search(pat, t)), 19)\n\n    if at is None and (m := re.search(r\"\\b(\\d+(?:[.,]\\d+)?|se|satu|one|an?)\\s*\" + _UNIT + r\"\\s*(sebelum|sebelumnya|before)\", t)) \\\n            or at is None and (m := re.search(r\"\\bh\\s*-\\s*(\\d+)\\b()\", t)) \\\n            or at is None and (m := re.search(r\"\\b(the)\\s+(day|night|evening) before\\b|\\b(malam) (sebelum\\w*)\", t)):\n        count, unit = m.group(1), m.group(2) or \"hari\"\n        if count in (\"the\", None):  # \"the day/night before\", \"malam sebelumnya\" = one day before\n            count, unit = \"1\", \"hari\"\n        if unit.startswith((\"hari\", \"day\")):  # N days before: that day, at the time given or the evening\n            day = due.date() - _delta(count, unit)\n            at = datetime.combine(day, time(hour if hour is not None else default_hour, minute or 0), tzinfo=WIB)\n        else:\n            at = due - _delta(count, unit)\n    if at is None and (m := re.search(r\"\\b(\\d+(?:[.,]\\d+)?|se|satu|one|an?)\\s*\" + _UNIT + r\"\\s*(lagi|dari sekarang|from now)\\b\", t)\n                       or re.search(r\"\\bin\\s+(\\d+(?:[.,]\\d+)?|an?|one)\\s*\" + _UNIT + r\"\\b\", t)):\n        at = n + _delta(m.group(1), m.group(2))\n    if at is None:\n        day, explicit_day = n.date(), False\n        if re.search(r\"\\b(hari ini|today|tonight|malam ini|nanti malam|sore ini|pagi ini|siang ini|this (morning|afternoon|evening))\\b\", t):\n            explicit_day = True\n        elif re.search(r\"\\b(lusa|day after tomorrow)\\b\", t):\n            day, explicit_day = n.date() + timedelta(days=2), True\n        elif re.search(r\"\\b(besok|besoknya|tomorrow)\\b\", t):\n            day, explicit_day = n.date() + timedelta(days=1), True\n        elif m := re.search(r\"\\b(\\d{4})-(\\d{2})-(\\d{2})\\b\", t):\n            day, explicit_day = datetime(int(m[1]), int(m[2]), int(m[3])).date(), True\n        elif m := re.search(r\"\\b(\\d{1,2})\\s+(\" + \"|\".join(sorted(_MONTH_WORDS, key=len, reverse=True)) + r\")\\b\", t):\n            day, explicit_day = datetime(n.year, _MONTH_WORDS[m[2]], int(m[1])).date(), True\n            if day < n.date():\n                day = day.replace(year=n.year + 1)\n        elif m := re.search(r\"\\b(\" + \"|\".join(_WEEKDAYS) + r\")\\b\", t):\n            day, explicit_day = n.date() + timedelta(days=(_WEEKDAYS[m[1]] - n.weekday()) % 7), True\n        if hour is None and not explicit_day and not any(re.search(p, t) for p, _, _ in _PART_OF_DAY):\n            return None, \"unclear\"\n        at = datetime.combine(day, time(hour if hour is not None else default_hour, minute or 0), tzinfo=WIB)\n        if at <= n and not explicit_day:\n            if hour is not None and hour < 12 and not re.search(r\"\\b(am|pagi|morning)\\b\", t) and at + timedelta(hours=12) > n:\n                at += timedelta(hours=12)  # \"jam 8\" said in the evening means 20:00\n            else:\n                at += timedelta(days=1)  # \"jam 7 pagi\" said tonight means tomorrow morning\n    return _check_remind_at(at, n, due)\n\n\ndef _check_remind_at(at: datetime, n: datetime, due: datetime) -> tuple[datetime | None, str | None]:\n    if at <= n:\n        return None, \"past\"\n    if at >= due:\n        return None, \"after_due\"\n    return at, None\n\n\n_TIME_WORDS = re.compile(\n    r\"\\b\\d+(?:[.,]\\d+)?\\s*\" + _UNIT + r\"\\b\"                      # 2 jam, 30 menit, 3 days\n    r\"|\\b(?:jam|pukul|pkl\\.?|at)\\s*\\d{1,2}(?:[:.]\\d{2})?\\b|@\\s*\\d{1,2}\"  # jam 8, at 9\n    r\"|\\b\\d{1,2}[:.]\\d{2}\\b|\\b\\d{1,2}\\s*(?:am|pm)\\b\"            # 20.00, 9pm\n    r\"|\\bh\\s*-\\s*\\d+\\b|\\b\\d{4}-\\d{2}-\\d{2}\\b\"                 # H-1, 2026-10-04\n    r\"|\\b\\d{1,2}\\s+(?:\" + \"|\".join(sorted(_MONTH_WORDS, key=len, reverse=True)) + r\")\\b\", re.I)\n\n\ndef strip_time_words(text: str) -> str:\n    \"\"\"The message without its time expressions, so \"2 jam sebelum deadline\" does not match \"Kuis 2\".\"\"\"\n    return _TIME_WORDS.sub(\" \", text or \"\")\n\n\ndef _remind_at_error(reason: str, item: data.ScheduleItem, n: datetime, lang: str) -> str:\n    due = fmt_dt(item.due, lang)\n    if reason == \"past\":\n        return (f\"Waktu itu sudah lewat (sekarang {fmt_dt(n, lang)}). Sebutkan waktu lain sebelum tenggat {due}.\"\n                if lang == \"id\" else f\"That time has already passed (it's now {fmt_dt(n, lang)}). Pick a time before the deadline, {due}.\")\n    if reason == \"after_due\":\n        return (f\"Waktu itu sudah melewati tenggatnya ({due}). Sebutkan waktu sebelum itu.\"\n                if lang == \"id\" else f\"That's after the deadline ({due}). Pick an earlier time.\")\n    return (\"Aku belum paham waktunya. Coba tulis seperti \\\"jam 8 malam\\\", \\\"besok 07.00\\\" atau \\\"2 jam sebelum tenggat\\\".\"\n            if lang == \"id\" else \"I couldn't work out the time. Try \\\"8pm tonight\\\", \\\"tomorrow 07:00\\\" or \\\"2 hours before the deadline\\\".\")\n\n\ndef _gcal_link(title: str, start: datetime, end: datetime, details: str) -> str:\n    fmt = \"%Y%m%dT%H%M%SZ\"\n    from datetime import timezone\n    s, e = start.astimezone(timezone.utc).strftime(fmt), end.astimezone(timezone.utc).strftime(fmt)\n    return (\"https://calendar.google.com/calendar/render?action=TEMPLATE\"\n            f\"&text={quote(title)}&dates={s}/{e}&details={quote(details)}&ctz=Asia/Jakarta\")\n\n\ndef _ics(events: list[dict]) -> str:\n    from datetime import timezone\n    fmt = \"%Y%m%dT%H%M%SZ\"\n    stamp = datetime.now(timezone.utc).strftime(fmt)\n    out = [\"BEGIN:VCALENDAR\", \"VERSION:2.0\", \"PRODID:-//Sigap//Smart School Service Center//ID\", \"CALSCALE:GREGORIAN\"]\n    for ev in events:\n        desc = ev[\"description\"].replace(\"\\\\\", \"\\\\\\\\\").replace(\"\\n\", \"\\\\n\").replace(\",\", \"\\\\,\").replace(\";\", \"\\\\;\")\n        out += [\n            \"BEGIN:VEVENT\", f\"UID:{uuid.uuid4()}@sigap\", f\"DTSTAMP:{stamp}\",\n            f\"DTSTART:{ev['start'].astimezone(timezone.utc).strftime(fmt)}\",\n            f\"DTEND:{ev['end'].astimezone(timezone.utc).strftime(fmt)}\",\n            f\"SUMMARY:{ev['title']}\", f\"DESCRIPTION:{desc}\",\n            \"BEGIN:VALARM\", \"TRIGGER:-PT15M\", \"ACTION:DISPLAY\", f\"DESCRIPTION:{ev['title']}\", \"END:VALARM\",\n            \"END:VEVENT\",\n        ]\n    out.append(\"END:VCALENDAR\")\n    return \"\\r\\n\".join(out) + \"\\r\\n\"\n\n\ndef create_study_reminder(item_id: str, student_confirmed: bool = False, language: str | None = None,\n                          remind_at: str | None = None, confirm_with: str = \"tool\") -> dict:\n    \"\"\"Creates calendar events for a deadline or exam: by default a reminder + study blocks, or, with remind_at\n    (the student's own words, e.g. \"jam 8 malam\"), one reminder at that time.\n    Writes nothing unless student_confirmed is True: without it, returns the proposed plan.\"\"\"\n    lang = _lang(language)\n    n = now()\n    item = find_item(item_id)\n    if not item:\n        return {\"tool\": \"create_study_reminder\", \"status\": \"ERROR\",\n                \"text\": f\"Item '{item_id}' tidak ada di jadwal resmi.\" if lang == \"id\" else f\"Item '{item_id}' is not in the official schedule.\"}\n    custom = None\n    if (remind_at or \"\").strip():\n        custom, reason = parse_remind_at(remind_at, n, item.due)\n        if reason:\n            return {\"tool\": \"create_study_reminder\", \"status\": \"INVALID_TIME\", \"reason\": reason, \"language\": lang,\n                    \"item\": item_dict(item, lang, n), \"text\": _remind_at_error(reason, item, n, lang)}\n    plan = {\"reminder\": custom, \"blocks\": []} if custom else plan_reminders(item, n)\n    title = f\"{item.course.name(lang)}: {item.title(lang)}\"\n    src_line = (f\"Sumber: {item.source} · tenggat {fmt_dt(item.due, lang, item.end)} · dibuat oleh Sigap atas persetujuan mahasiswa\"\n                if lang == \"id\" else\n                f\"Source: {item.source} · due {fmt_dt(item.due, lang, item.end)} · created by Sigap with the student's consent\")\n    events = []\n    if plan[\"reminder\"]:\n        r = plan[\"reminder\"]\n        events.append({\"kind\": \"reminder\", \"title\": f\"⏰ {'Pengingat' if lang == 'id' else 'Reminder'} — {title}\",\n                       \"start\": r, \"end\": r + timedelta(minutes=15), \"description\": src_line})\n    for a, b in plan[\"blocks\"]:\n        events.append({\"kind\": \"study_block\", \"title\": f\"📚 {'Belajar' if lang == 'id' else 'Study'} — {title}\",\n                       \"start\": a, \"end\": b, \"description\": src_line})\n\n    def ev_text(ev):\n        label = (\"Pengingat\" if lang == \"id\" else \"Reminder\") if ev[\"kind\"] == \"reminder\" else (\"Blok belajar\" if lang == \"id\" else \"Study block\")\n        when = fmt_dt(ev[\"start\"], lang) if ev[\"kind\"] == \"reminder\" else fmt_dt(ev[\"start\"], lang, ev[\"end\"])\n        return f\"- {label}: {when}\"\n\n    plan_lines = [ev_text(ev) for ev in events]\n    base = {\"tool\": \"create_study_reminder\", \"language\": lang, \"item\": item_dict(item, lang, n),\n            \"events\": [{\"kind\": e[\"kind\"], \"title\": e[\"title\"], \"start\": e[\"start\"].isoformat(), \"end\": e[\"end\"].isoformat()} for e in events]}\n    if custom:\n        base[\"remind_at\"] = custom.isoformat()\n    if not events:\n        return base | {\"status\": \"NOTHING_TO_SCHEDULE\",\n                       \"text\": \"Tenggatnya terlalu dekat untuk dijadwalkan pengingat.\" if lang == \"id\" else \"The deadline is too close to schedule a reminder.\"}\n    if not student_confirmed:\n        q = (_BUTTON_NOTE[lang] if confirm_with == \"button\" else\n             \"Rencana ini BELUM dibuat. Tanyakan dulu ke mahasiswa; panggil lagi dengan student_confirmed=true hanya setelah ia menjawab ya.\"\n             if lang == \"id\" else\n             \"This plan has NOT been created. Ask the student first; call again with student_confirmed=true only after they say yes.\")\n        return base | {\"status\": \"NEEDS_CONFIRMATION\", \"text\": \"\\n\".join([title, *plan_lines, \"\", q])}\n\n    folder = OUTBOX_DIR / \"calendar\"\n    folder.mkdir(parents=True, exist_ok=True)\n    fname = f\"{item.item_id}-{uuid.uuid4().hex[:6]}.ics\"\n    (folder / fname).write_text(_ics(events), encoding=\"utf-8\")\n    for ev in events:\n        ev[\"google_calendar_link\"] = _gcal_link(ev[\"title\"], ev[\"start\"], ev[\"end\"], ev[\"description\"])\n    _append_csv(OUTBOX_DIR / \"calendar_log.csv\", {\n        \"created_at\": n.isoformat(), \"item_id\": item.item_id,\n        \"events\": len(events), \"ics_file\": fname,\n    })\n    done = (f\"Sudah dibuat {len(events)} acara kalender untuk {title}:\" if lang == \"id\"\n            else f\"Created {len(events)} calendar events for {title}:\")\n    return base | {\n        \"status\": \"CREATED\",\n        \"ics_file\": f\"/outbox/calendar/{fname}\",\n        \"events\": [{\"kind\": e[\"kind\"], \"title\": e[\"title\"], \"start\": e[\"start\"].isoformat(), \"end\": e[\"end\"].isoformat(),\n                    \"google_calendar_link\": e[\"google_calendar_link\"]} for e in events],\n        \"text\": \"\\n\".join([done, *plan_lines, \"\", src_line]),\n    }\n\n\n# ---------------------------------------------------------------- tool 5\n\nOFFICES = {\n    \"akademik\": (\"Bagian Layanan Akademik\", \"Academic Services\", STUDENT_SERVICES_INBOX),\n    \"keuangan\": (\"Biro Keuangan\", \"Finance Bureau\", \"keuangan@und.ac.id\"),\n    \"ti\": (\"Helpdesk TI\", \"IT Helpdesk\", \"helpdesk@und.ac.id\"),\n    \"umum\": (\"Bagian Layanan Akademik\", \"Academic Services\", STUDENT_SERVICES_INBOX),\n}\n\n\ndef guess_category(question: str) -> str:\n    q = question.lower()\n    if re.search(r\"ukt|bayar|biaya|tuition|fee|payment|refund|beasiswa|scholarship|keuangan|finance\", q):\n        return \"keuangan\"\n    if re.search(r\"login|password|wifi|wi-fi|akun|account|lms (error|down)|email kampus|sso\", q):\n        return \"ti\"\n    if re.search(r\"nilai|grade|krs|ujian|exam|cuti|leave|dosen|lecturer|kuliah|course|transkrip|transcript|skripsi|thesis|magang|internship|jurusan|major\", q):\n        return \"akademik\"\n    return \"umum\"\n\n\ndef _append_csv(path, row: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    new = not path.exists()\n    with open(path, \"a\", newline=\"\", encoding=\"utf-8\") as f:\n        w = csv.DictWriter(f, fieldnames=list(row))\n        if new:\n            w.writeheader()\n        w.writerow(row)\n\n\ndef _next_reference(n: datetime) -> str:\n    log = OUTBOX_DIR / \"tickets.csv\"\n    count = 0\n    if log.exists():\n        with open(log, encoding=\"utf-8\") as f:\n            count = sum(1 for _ in f) - 1\n    return f\"SGP-{n:%y%m%d}-{count + 1:04d}\"\n\n\ndef escalate_to_student_services(question: str, category: str | None = None, course: str | None = None,\n                                 checked_sources: list[str] | None = None, language: str | None = None,\n                                 student_confirmed: bool = False, reference: str | None = None,\n                                 confirm_with: str = \"tool\") -> dict:\n    \"\"\"Sends a question Sigap could not answer to student services with a case summary.\n    Sends nothing unless student_confirmed is True: without it, returns a preview of what would be sent.\"\"\"\n    lang = _lang(language, question)\n    n = now()\n    cat = category if category in OFFICES else guess_category(question)\n    office_id, office_en, inbox = OFFICES[cat]\n    office = office_en if lang == \"en\" else office_id\n    checked = checked_sources or [f\"{d.title(lang)} v{d.meta.get('version')}\" for d in data.documents()] + [\n        \"Kalender Akademik Ganjil 2026/2027\", \"Jadwal mata kuliah resmi\"]\n    c = find_course(course or question)\n    base = {\"tool\": \"escalate_to_student_services\", \"language\": lang, \"office\": office, \"inbox\": inbox, \"category\": cat}\n    if not student_confirmed:\n        preview = (f\"Akan dikirim ke {office} ({inbox}): pertanyaan, kategori '{cat}'\"\n                   + (f\", mata kuliah {c.name(lang)}\" if c else \"\")\n                   + \", dan daftar sumber yang sudah dicek. Tanpa NIM atau data pribadi lain. BELUM dikirim — tunggu persetujuan mahasiswa.\"\n                   if lang == \"id\" else\n                   f\"Will send to {office} ({inbox}): the question, category '{cat}'\"\n                   + (f\", course {c.name(lang)}\" if c else \"\")\n                   + \", and the sources already checked. No student ID or other personal data. NOT sent yet — wait for the student's yes.\")\n        if confirm_with == \"button\":\n            preview += \"\\n\" + _BUTTON_NOTE[lang]\n        return base | {\"status\": \"NEEDS_CONFIRMATION\", \"text\": preview}\n\n    ref = reference or _next_reference(n)\n    body = \"\\n\".join([\n        f\"Reference: {ref}\",\n        f\"Received: {n:%Y-%m-%d %H:%M} WIB\",\n        f\"Category: {cat}\",\n        f\"Course: {c.code + ' ' + c.name_id if c else '-'}\",\n        f\"Student language: {'Bahasa Indonesia' if lang == 'id' else 'English'}\",\n        \"Student: identity is kept in the Sigap admin panel; open this reference there to reply.\",\n        \"\",\n        \"Question (verbatim):\",\n        question,\n        \"\",\n        \"What Sigap already checked (no answer found):\",\n        *[f\"- {s}\" for s in checked],\n        \"\",\n        \"Please reply to the student through the portal ticket. If the answer is general, mark it for the knowledge base (FR-8).\",\n    ])\n    msg = EmailMessage()\n    msg[\"From\"] = os.environ.get(\"SIGAP_SMTP_FROM\", \"sigap-bot@und.ac.id\")\n    msg[\"To\"] = inbox\n    msg[\"Subject\"] = f\"[Sigap {ref}] {cat.title()}: {question[:60]}\"\n    msg.set_content(body)\n    folder = OUTBOX_DIR / \"emails\"\n    folder.mkdir(parents=True, exist_ok=True)\n    (folder / f\"{ref}.eml\").write_bytes(bytes(msg))\n    delivered = \"outbox\"\n    if os.environ.get(\"SIGAP_SMTP_HOST\"):\n        with smtplib.SMTP(os.environ[\"SIGAP_SMTP_HOST\"], int(os.environ.get(\"SIGAP_SMTP_PORT\", \"587\"))) as s:\n            s.starttls()\n            if os.environ.get(\"SIGAP_SMTP_USER\"):\n                s.login(os.environ[\"SIGAP_SMTP_USER\"], os.environ[\"SIGAP_SMTP_PASSWORD\"])\n            s.send_message(msg)\n        delivered = \"smtp\"\n    _append_csv(OUTBOX_DIR / \"tickets.csv\", {\n        \"reference\": ref, \"created_at\": n.isoformat(), \"status\": \"open\", \"category\": cat, \"office\": office_id,\n        \"course\": c.code if c else \"\", \"language\": lang, \"question\": question,\n        \"checked_sources\": json.dumps(checked, ensure_ascii=False), \"delivered_via\": delivered,\n    })\n    nxt = (f\"{office} akan membalas dalam 2 hari kerja (Sen–Jum 08.00–16.00 WIB); balasannya dikirim ke tempat kamu bertanya. \"\n           \"Simpan nomor referensi ini untuk mengecek statusnya.\"\n           if lang == \"id\" else\n           f\"{office} will reply within 2 working days (Mon–Fri 08:00–16:00 WIB), right where you asked. \"\n           \"Keep this reference number to check its status.\")\n    head = f\"Terkirim ke {office}. Nomor referensi: {ref}\" if lang == \"id\" else f\"Sent to {office}. Reference number: {ref}\"\n    return base | {\"status\": \"SENT\", \"reference\": ref, \"next_step\": nxt, \"text\": f\"{head}\\n{nxt}\"}\n"}


def load_sigap(data_files):
    """Loads the bundled sigap package once per (code, data) version under a private module name."""
    digest = hashlib.sha256(json.dumps([SIGAP_SOURCES, data_files], sort_keys=True).encode()).hexdigest()[:12]
    pkg = f"_sigap_{digest}"
    if pkg + ".tools" in sys.modules:
        return sys.modules[pkg + ".tools"]
    base = Path(tempfile.gettempdir()) / pkg
    for rel, content in data_files.items():
        path = base / "data" / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
    if not os.environ.get("SIGAP_OUTBOX_DIR"):
        persistent = Path("/app/langflow")
        os.environ["SIGAP_OUTBOX_DIR"] = str(persistent / "sigap-outbox" if persistent.is_dir() else base / "outbox")
    previous = os.environ.get("SIGAP_DATA_DIR")
    os.environ["SIGAP_DATA_DIR"] = str(base / "data")
    try:
        for name in ['__init__', 'config', 'textutil', 'data', 'retrieval', 'tools']:
            full = pkg if name == "__init__" else f"{pkg}.{name}"
            mod = types.ModuleType(full)
            mod.__file__ = str(base / "sigap" / f"{name}.py")
            mod.__package__ = pkg
            if name == "__init__":
                mod.__path__ = []
            sys.modules[full] = mod
            exec(compile(SIGAP_SOURCES[name], mod.__file__, "exec"), mod.__dict__)
            if name != "__init__":
                setattr(sys.modules[pkg], name, mod)
    finally:
        if previous is None:
            os.environ.pop("SIGAP_DATA_DIR", None)
        else:
            os.environ["SIGAP_DATA_DIR"] = previous
    return sys.modules[pkg + ".tools"]


def parse_args(text):
    """Accepts a JSON object, 'key=value; key=value' text, or plain text (the question/request)."""
    text = (text or "").strip()
    if text.startswith("{"):
        try:
            value = json.loads(text)
            if isinstance(value, dict):
                return value
        except json.JSONDecodeError:
            pass
    pairs = dict(re.findall(r"(\w+)\s*=\s*([^;\n]+)", text))
    if pairs and all(k in {"item_id", "student_confirmed", "language", "course", "item_type", "category", "on_date", "topic"} for k in pairs):
        return {k: v.strip() for k, v in pairs.items()}
    return {"request": text, "question": text, "item_id": text}


def truthy(value):
    return str(value).strip().lower() in {"true", "yes", "ya", "1", "y"}


class SigapEscalateToStudentServices(Component):
    display_name = "Sigap · Escalate to Staff"
    description = 'Hands a question to staff with a reference number, only after yes.'
    icon = "life-buoy"
    name = "SigapEscalateToStudentServices"

    inputs = [
        MessageTextInput(name="input_value", display_name="Input", info='Plain text or JSON arguments. Sends a question Sigap could not answer to the student-services inbox with a case summary and returns a reference number and the next step. Input JSON {"question": ..., "category": "akademik|keuangan|ti|umum", "course": ..., "language": ..., "student_confirmed": false}. Call ONLY after the student agrees; without student_confirmed=true nothing is sent and a preview is returned. Never include student ID numbers.', required=True, tool_mode=True),
        MultilineInput(name='courses_csv', display_name='Courses (CSV)', info='Course codes, names and aliases.',
                       value='course_code,name_id,name_en,lecturer,aliases\nIF2101,Struktur Data,Data Structures,Dr. Rina Kusuma (fiktif),strukdat;struktur data;data structures;data structure;sd;if2101\nSI2203,Basis Data,Database Systems,Bagus Wicaksono M.Kom. (fiktif),basdat;basis data;database;databases;database systems;si2203\nSI2105,Analisis dan Perancangan Sistem,Systems Analysis and Design,Dr. Maya Lestari (fiktif),aps;anperancang;analisis dan perancangan sistem;systems analysis;system analysis;systems analysis and design;si2105\nMA2102,Statistika,Statistics,Andi Saputra M.Si. (fiktif),statistika;statistik;stats;statistics;ma2102\nSI2207,Interaksi Manusia dan Komputer,Human-Computer Interaction,Dewi Anggraini M.T. (fiktif),imk;interaksi manusia dan komputer;hci;human-computer interaction;human computer interaction;si2207\nUM2001,Bahasa Inggris Akademik,Academic English,Sarah Hutapea M.A. (fiktif),bahasa inggris;b. inggris;academic english;english;bing;um2001\n'),
        MultilineInput(name='handbook_md', display_name='Handbook (Markdown)', info="Official handbook, one '## number | title ID | title EN' block per section.",
                       value="---\ntitle_id: Pedoman Akademik Program Sarjana 2026/2027\ntitle_en: Undergraduate Academic Handbook 2026/2027\ninstitution: Universitas Nusantara Digital (kampus fiktif untuk demo)\nversion: 1.2\neffective: 2026-08-01\nnote: Contoh pedoman yang ditulis tim Sigap sebagai pengganti dokumen resmi kampus. Bukan aturan kampus nyata.\n---\n\n## 3.1 | Kehadiran Minimum | Minimum Attendance\ntags: hadir, kehadiran, absen, absensi, presensi, attendance, minimal, minimum, persen, 75, syarat, uas, ujian, daring, online\nID: Mahasiswa wajib hadir minimal 75% dari pertemuan setiap mata kuliah. Untuk kelas daring, kehadiran dihitung dari aktivitas yang tercatat di LMS (mengerjakan aktivitas mingguan atau mengikuti sesi sinkron). Mahasiswa dengan kehadiran di bawah 75% tidak boleh mengikuti UAS mata kuliah tersebut.\nEN: Students must attend at least 75% of the meetings of each course. For online classes, attendance is counted from activity recorded in the LMS (completing the weekly activity or joining the live session). Students below 75% attendance may not sit the final exam (UAS) for that course.\n\n## 3.2 | Izin Tidak Hadir | Excused Absence\ntags: izin, sakit, surat, dokter, absen, hadir, permission, sick, excused, absence, keterangan, darurat, emergency\nID: Ketidakhadiran karena sakit atau keadaan darurat harus dilaporkan lewat menu Izin di portal akademik paling lambat 3 hari kerja setelah tidak hadir, disertai surat keterangan dokter atau bukti pendukung. Izin yang disetujui tidak mengurangi persentase kehadiran, dengan batas paling banyak 3 pertemuan per mata kuliah.\nEN: Absence due to illness or an emergency must be reported through the Permission menu in the academic portal within 3 working days, with a doctor's note or other supporting evidence. Approved permissions do not reduce the attendance percentage, up to a maximum of 3 meetings per course.\n\n## 4.1 | Pengumpulan Tugas Lewat LMS | Submitting Assignments Through the LMS\ntags: kumpul, unggah, upload, submit, tugas, lms, email, kanal, resmi, gangguan, error, down, format, file\nID: Semua tugas dikumpulkan lewat LMS sesuai tenggat yang tertulis di halaman mata kuliah. Tugas yang dikirim lewat email atau WhatsApp tidak dihitung, kecuali LMS mengalami gangguan yang diumumkan resmi oleh Direktorat TI; dalam kondisi itu tugas dikirim ke email dosen sebelum tenggat dengan menyertakan tangkapan layar gangguan.\nEN: All assignments are submitted through the LMS by the deadline shown on the course page. Work sent by email or WhatsApp is not counted, unless the LMS has an outage officially announced by the IT Directorate; in that case the work goes to the lecturer's email before the deadline together with a screenshot of the error.\n\n## 4.2 | Keterlambatan Pengumpulan Tugas | Late Assignment Submission\ntags: terlambat, telat, late, kumpul, submit, tugas, assignment, potong, potongan, penalti, penalty, nilai, dinilai, graded, lewat, tenggat\nID: Tugas yang terlambat tetap dinilai dengan potongan: terlambat sampai 24 jam dipotong 20%, terlambat lebih dari 24 jam sampai 72 jam dipotong 50%, dan lebih dari 72 jam mendapat nilai 0. Potongan tidak berlaku bila mahasiswa sudah mendapat perpanjangan tenggat sesuai Pasal 4.3. Kuis dan ujian tidak dapat dikerjakan terlambat.\nEN: Late assignments are still graded with a penalty: up to 24 hours late loses 20%, more than 24 and up to 72 hours late loses 50%, and more than 72 hours late scores 0. No penalty applies if the student was granted an extension under Article 4.3. Quizzes and exams cannot be taken late.\n\n## 4.3 | Perpanjangan Tenggat Tugas | Assignment Extensions\ntags: perpanjang, perpanjangan, extension, extend, tenggat, deadline, tambahan, waktu, minta, request, dosen, alasan, sakit, darurat\nID: Perpanjangan tenggat diajukan langsung kepada dosen pengampu sebelum tenggat berakhir, dengan alasan dan bukti (misalnya sakit, musibah, atau tugas kantor bagi mahasiswa kelas karyawan). Perpanjangan paling lama 7 hari dan keputusan sepenuhnya ada pada dosen. Permintaan setelah tenggat lewat tidak diproses.\nEN: Extensions are requested directly from the course lecturer before the deadline passes, with a reason and evidence (for example illness, bereavement, or work duties for working-student classes). An extension is at most 7 days and the decision rests entirely with the lecturer. Requests made after the deadline are not processed.\n\n## 4.4 | Integritas Akademik dan Penggunaan AI | Academic Integrity and AI Use\ntags: plagiat, plagiarisme, plagiarism, curang, nyontek, contek, cheating, ai, chatgpt, joki, integritas, integrity, sanksi, sanction, salin, copy\nID: Plagiarisme, menyontek, menggunakan jasa joki, dan menyerahkan karya buatan AI sebagai karya sendiri adalah pelanggaran integritas akademik. Penggunaan alat AI hanya boleh bila diizinkan dosen dan wajib disebutkan. Sanksi bertingkat mulai dari nilai 0 untuk tugas tersebut, nilai E untuk mata kuliah, sampai skorsing satu semester.\nEN: Plagiarism, cheating, using a ghost-writing service, and submitting AI-generated work as one's own are violations of academic integrity. AI tools may be used only when the lecturer allows it, and their use must be disclosed. Sanctions escalate from a 0 for the assignment, to an E for the course, up to a one-semester suspension.\n\n## 5.1 | Ujian Susulan | Make-up Exams\ntags: susulan, makeup, ujian, uts, uas, sakit, ikut, missed, miss, absen, darurat, kaprodi, ajukan\nID: Mahasiswa yang tidak dapat mengikuti UTS atau UAS karena sakit, musibah, atau tugas negara dapat mengajukan ujian susulan lewat portal akademik paling lambat 2 hari kerja setelah jadwal ujian, dengan bukti pendukung. Pengajuan disetujui oleh Ketua Program Studi dan ujian susulan tidak dipungut biaya.\nEN: Students who cannot sit a midterm (UTS) or final (UAS) because of illness, bereavement, or state duty may request a make-up exam through the academic portal no later than 2 working days after the exam, with supporting evidence. Requests are approved by the Head of Study Program and make-up exams are free of charge.\n\n## 5.2 | Syarat Mengikuti Ujian | Exam Eligibility\ntags: syarat, ujian, uts, uas, ikut, eligible, eligibility, kartu, ukt, bayar, lunas, hadir, requirement, boleh\nID: Untuk mengikuti UTS dan UAS mahasiswa harus terdaftar di mata kuliah pada KRS, tidak memiliki tunggakan UKT untuk cicilan yang sudah jatuh tempo, dan memiliki kartu ujian digital dari portal akademik. Khusus UAS, kehadiran minimal 75% (Pasal 3.1) juga berlaku.\nEN: To sit the midterm (UTS) and final (UAS), students must be registered for the course in their KRS, have no overdue tuition (UKT) installments, and hold the digital exam card from the academic portal. For the final exam, the 75% minimum attendance (Article 3.1) also applies.\n\n## 5.3 | Tata Tertib Ujian Daring | Online Exam Rules\ntags: ujian, daring, online, kamera, camera, pengawas, proctoring, proctor, terlambat, telat, late, koneksi, internet, putus, tata, tertib\nID: Selama ujian daring kamera wajib menyala dan proctoring LMS aktif. Mahasiswa yang terlambat lebih dari 15 menit tidak boleh mengikuti ujian. Bila koneksi terputus, mahasiswa segera melapor ke pengawas lewat kanal yang diumumkan dan dapat melanjutkan ujian dalam sisa waktu yang ada.\nEN: During online exams the camera must stay on and LMS proctoring must be active. Students more than 15 minutes late may not sit the exam. If the connection drops, the student reports to the proctor through the announced channel straight away and may continue within the remaining time.\n\n## 6.1 | Skala Nilai | Grading Scale\ntags: skala, nilai, huruf, angka, grade, grading, scale, ipk, gpa, bobot, lulus, pass, minimum\nID: Nilai huruf ditetapkan dari nilai angka: A (85–100, bobot 4,0), AB (78–84, 3,5), B (70–77, 3,0), BC (63–69, 2,5), C (55–62, 2,0), D (45–54, 1,0), dan E (di bawah 45, 0). Nilai minimal lulus mata kuliah adalah C.\nEN: Letter grades come from numeric scores: A (85–100, weight 4.0), AB (78–84, 3.5), B (70–77, 3.0), BC (63–69, 2.5), C (55–62, 2.0), D (45–54, 1.0) and E (below 45, 0). The minimum passing grade for a course is C.\n\n## 6.2 | Banding Nilai Akhir | Final Grade Appeals\ntags: banding, appeal, keberatan, nilai, akhir, final, salah, koreksi, review, dosen, kaprodi\nID: Keberatan atas nilai akhir mata kuliah diajukan lewat formulir Banding Nilai di portal akademik dalam masa banding yang tercantum di kalender akademik. Dosen menanggapi paling lambat 5 hari kerja; bila mahasiswa belum puas, banding diteruskan ke Ketua Program Studi yang keputusannya bersifat final.\nEN: Objections to a final course grade are filed with the Grade Appeal form in the academic portal during the appeal window listed in the academic calendar. The lecturer responds within 5 working days; if the student is still not satisfied, the appeal goes to the Head of Study Program, whose decision is final.\n\n## 6.3 | Mengulang Mata Kuliah | Retaking a Course\ntags: ulang, mengulang, retake, repeat, remedial, perbaikan, improve, d, e, gagal, fail, tidak lulus\nID: Mata kuliah dengan nilai D atau E dapat diulang pada semester berikutnya saat mata kuliah itu ditawarkan, dengan mengambilnya kembali di KRS. Nilai yang dipakai adalah nilai terbaik. Tidak ada ujian remedial di luar jadwal kecuali diadakan oleh dosen untuk seluruh kelas.\nEN: Courses graded D or E can be retaken in a later semester when the course is offered, by adding it to the KRS again. The best grade counts. There are no individual remedial exams unless the lecturer holds one for the whole class.\n\n## 7.1 | Cuti Akademik | Academic Leave\ntags: cuti, leave, berhenti, sementara, istirahat, formulir, prosedur, cara, ajukan, apply, dekan, biaya\nID: Cuti akademik diajukan lewat formulir Cuti di portal akademik dalam masa pengajuan cuti pada kalender akademik, setelah disetujui dosen wali. Cuti paling lama 2 semester selama masa studi, tidak dihitung dalam masa studi, dan mahasiswa membayar biaya cuti sebesar 25% UKT. Persetujuan akhir diberikan oleh Dekan.\nEN: Academic leave is requested through the Leave form in the academic portal during the leave-application window in the academic calendar, after approval from the academic advisor. Leave may total at most 2 semesters, does not count toward the study period, and the student pays a leave fee of 25% of tuition (UKT). Final approval is given by the Dean.\n\n## 7.2 | Pembatalan Mata Kuliah | Course Withdrawal\ntags: batal, pembatalan, withdraw, withdrawal, drop, mundur, refund, transkrip, ajukan\nID: Mahasiswa dapat membatalkan mata kuliah setelah masa perubahan KRS, selama masa pembatalan mata kuliah di kalender akademik. Mata kuliah yang dibatalkan tercatat dengan nilai W di transkrip, tidak dihitung dalam IPK, dan biaya tidak dikembalikan.\nEN: Students may withdraw from a course after the add/drop period, during the course-withdrawal window in the academic calendar. A withdrawn course appears as W on the transcript, does not count toward the GPA, and fees are not refunded.\n\n## 7.3 | Pengisian dan Perubahan KRS | Course Registration and Add/Drop\ntags: krs, registrasi, registration, register, enroll, isi, tambah, add, drop, ubah, perubahan, sks, beban, maksimal, dosen, wali\nID: KRS diisi lewat portal akademik dalam masa pengisian KRS dan disetujui dosen wali. Beban maksimal 24 SKS bila IP semester sebelumnya 3,00 atau lebih, dan 20 SKS bila di bawahnya. Mata kuliah dapat ditambah atau dibatalkan tanpa catatan selama masa perubahan KRS.\nEN: The KRS is filled in through the academic portal during the course-registration window and approved by the academic advisor. The maximum load is 24 credits if the previous semester GPA is 3.00 or higher, and 20 credits otherwise. Courses can be added or dropped without a record during the add/drop period.\n\n## 8.1 | Pembayaran UKT dan Cicilan | Tuition Payment and Installments\ntags: ukt, bayar, pembayaran, tuition, fee, payment, cicil, cicilan, installment, tunggakan, telat, terlambat, denda, va, virtual\nID: UKT dapat dibayar penuh atau dalam 3 cicilan sesuai jadwal di kalender akademik, lewat virtual account di portal keuangan. Mahasiswa dengan cicilan yang lewat jatuh tempo tidak dapat mengisi KRS dan tidak mendapat kartu ujian sampai tunggakan dilunasi. Keringanan pembayaran diajukan ke Biro Keuangan.\nEN: Tuition (UKT) can be paid in full or in 3 installments following the academic calendar, through the virtual account in the finance portal. Students with an overdue installment cannot fill in the KRS and do not receive an exam card until the balance is paid. Payment relief is requested from the Finance Bureau.\n\n## 9.1 | Layanan Mahasiswa | Student Services\ntags: layanan, service, services, kontak, contact, jam, hours, kantor, office, helpdesk, akademik, bagian\nID: Bagian Layanan Akademik melayani pertanyaan akademik lewat email layanan.akademik@und.ac.id dan loket daring di portal, Senin–Jumat pukul 08.00–16.00 WIB. Pertanyaan keuangan ditujukan ke Biro Keuangan (keuangan@und.ac.id) dan masalah akun atau LMS ke Helpdesk TI (helpdesk@und.ac.id).\nEN: Academic Services answers academic questions by email at layanan.akademik@und.ac.id and through the online counter in the portal, Monday–Friday 08:00–16:00 WIB. Finance questions go to the Finance Bureau (keuangan@und.ac.id) and account or LMS problems to the IT Helpdesk (helpdesk@und.ac.id).\n\n## 9.2 | Konseling Mahasiswa | Student Counselling\ntags: konseling, counseling, counselling, psikolog, stres, stress, cemas, anxiety, depresi, depressed, mental, curhat, burnout, lelah\nID: Unit Konseling menyediakan konseling gratis dan rahasia dengan psikolog, daring maupun tatap muka. Jadwalkan lewat konseling@und.ac.id atau WhatsApp 0812-0000-0000 (Senin–Jumat 09.00–17.00 WIB). Dalam keadaan darurat, hubungi 119 ext. 8.\nEN: The Counselling Unit offers free, confidential sessions with a psychologist, online or in person. Book through konseling@und.ac.id or WhatsApp 0812-0000-0000 (Monday–Friday 09:00–17:00 WIB). In an emergency, call 119 ext. 8.\n"),
        StrInput(name="demo_now", display_name="Demo time (WIB)", value="2026-10-04T19:00", advanced=True,
                 info="Pins 'now' for reproducible demos, e.g. 2026-10-04T19:00. Empty = real clock."),
        BoolInput(name="allow_actions", display_name="Allow confirmed actions", value=True, advanced=True,
                  info="Off = preview only, even if the caller says student_confirmed (use inside agents)."),

    ]
    outputs = [
        Output(display_name="Result", name="result", method="run_tool"),
    ]

    def run_tool(self) -> Message:
        if self.demo_now:
            os.environ["SIGAP_NOW"] = self.demo_now
        else:
            os.environ.pop("SIGAP_NOW", None)
        tools = load_sigap({'courses.csv': self.courses_csv, 'handbook/pedoman_akademik_v1.2.md': self.handbook_md})
        a = parse_args(self.input_value)

        result = tools.escalate_to_student_services(a.get('question') or a.get('request', ''), a.get('category'), a.get('course'), a.get('checked_sources'), a.get('language'), truthy(a.get('student_confirmed')) and self.allow_actions, a.get('reference'), confirm_with='tool' if self.allow_actions else 'button')
        payload = {k: v for k, v in result.items() if k != "text"}
        text = result["text"] + "\n\n---\n```json\n" + json.dumps(payload, ensure_ascii=False, indent=1) + "\n```"
        self.status = result.get("status") or result.get("tool")
        return Message(text=text)
